/* @socom-skeleton stub QFromRot__FP5CQuatPC6CPnt3D */
CQuat * QFromRot(CQuat *out, const CPnt3D *rot)
{
	/* 0x1dd080: the euler rotation as z * y * x */
	CQuat qx, qy, qz, qzy;
	qx.MakeXRot(rot->x);
	qy.MakeYRot(rot->y);
	qz.MakeZRot(rot->z);
	qz.Mul(&qy, &qzy);
	qzy.Mul(&qx, out);
	return out;
}

/* @socom-skeleton stub quadW__Ff */
float quadW(float w)
{
	/* 0x1dd020: ease in-out */
	if (w <= 0.5f)
		return w * 2.0f * w;

	f32 d = (w - 1.0f) * 2.0f;
	return 1.0f - d * 0.5f * d;
}

